import sys


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    head = int(data[0])
    direction = data[1].lower()
    max_cylinder = int(data[2])
    n = int(data[3])
    requests = [int(x) for x in data[4:4 + n]]

    if direction == "left":
        boundary = 0
    else:
        boundary = max_cylinder

    total = abs(head - boundary)
    if direction == "left":
        remaining = [c for c in requests if c > head]
        if remaining:
            total += abs(boundary - max(remaining))
    else:
        remaining = [c for c in requests if c < head]
        if remaining:
            total += abs(boundary - min(remaining))

    print(total)


main()

import sys


def run(blocks, sizes, mode):
    memory = [list(b) for b in blocks]
    result = []
    for want in sizes:
        pick = -1
        if mode == "first":
            for index in range(len(memory)):
                if memory[index][1] >= want:
                    pick = index
                    break
        else:
            for index in range(len(memory)):
                if memory[index][1] < want:
                    continue
                if pick == -1:
                    pick = index
                elif memory[index][1] < memory[pick][1]:
                    pick = index
                elif memory[index][1] == memory[pick][1] and memory[index][0] < memory[pick][0]:
                    pick = index
        if pick == -1:
            result.append(-1)
            continue
        base, size = memory[pick]
        result.append(base)
        if size == want:
            memory.pop(pick)
        else:
            memory[pick] = [base + want, size - want]
    return result


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    idx = 0
    k = int(data[idx])
    idx += 1
    blocks = []
    for _ in range(k):
        base = int(data[idx])
        size = int(data[idx + 1])
        idx += 2
        blocks.append([base, size])
    q = int(data[idx])
    idx += 1
    sizes = [int(x) for x in data[idx:idx + q]]

    first = run(blocks, sizes, "first")
    best = run(blocks, sizes, "best")
    print(" ".join(str(x) for x in first + best))


main()
